<?php
namespace Delnavazan\Platform\Core\Application;
use Delnavazan\Platform\Core\Infrastructure\Repository\OperationalExceptionRepository;
final class ExceptionService { private const TYPES=['core_integrity_failure','migration_failed','migration_lock_stale','invalid_entity_relationship','duplicate_identity_candidate','schedule_conflict','timezone_missing','reference_generation_failed','archive_conflict','unknown_system_error']; public function record(array $d):int{return $this->recordTrusted($d);} public function recordTrusted(array $d):int{$d['exception_type']=Normalizer::one($d['exception_type']??'',self::TYPES,'exception type');$d['severity']=Normalizer::one($d['severity']??'error',['info','warning','error','critical'],'severity');$d['summary']=Normalizer::text($d['summary']??'',255,true);$d['safe_detail']=Normalizer::text($d['safe_detail']??null,65535);if($d['safe_detail']&&preg_match('/token|secret|password|authorization/i',$d['safe_detail']))throw new \InvalidArgumentException('Unsafe exception detail');$d['fingerprint']=hash('sha256',$d['exception_type'].'|'.($d['entity_type']??'system').'|'.($d['entity_id']??''));$d['status']='open';$d['detected_at']=$d['last_seen_at']=gmdate('Y-m-d H:i:s');$d['uid']=\Delnavazan\Platform\Core\Support\Identifier::uid();$repo=new OperationalExceptionRepository;$existing=$repo->activeFingerprint($d['fingerprint']);if($existing){$repo->seen((int)$existing->id,$d['last_seen_at']);return(int)$existing->id;}return $repo->insert($d);} public function incrementRetry(int $id):void{if(!current_user_can('dzn_manage_exceptions'))throw new \RuntimeException('Unauthorized');(new OperationalExceptionRepository)->incrementRetry($id);} public function transition(int $id,string $to,?string $note=null):void{if(!current_user_can('dzn_manage_exceptions'))throw new \RuntimeException('Unauthorized');$repo=new OperationalExceptionRepository;$e=$repo->find($id);if(!$e||!in_array($e->status,['open','acknowledged'],true)||!in_array($to,['acknowledged','resolved','dismissed'],true))throw new \InvalidArgumentException('Invalid exception transition');$repo->transition($id,$to,gmdate('Y-m-d H:i:s'),get_current_user_id()?:null,Normalizer::text($note,65535));} }
